import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { validateAuthCallbackWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await validateAuthCallbackWorkflow(req.scope).run({
    input: {
      actor_type: "customer",
      auth_provider: "github",
      auth_data: {
        query: { code: "123", state: "456" },
      },
    },
  })

  res.send(result)
}

